SELECT "__time" AS "time", "__c0" AS "sensor.ENERGY.Total" FROM (SELECT sub0.time AS "__time", (sub0.value - lag(sub0.value) OVER (ORDER BY sub0.time)) AS "__c0" FROM (SELECT time_bucket('6h', "time", 'Europe/Berlin') AS "time", avg("sensor.ENERGY.Total") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" >= time_bucket('6h', time_bucket('6h', '2026-01-01T00:00:00Z'::timestamptz, 'Europe/Berlin') - interval '1 microsecond', 'Europe/Berlin') AND "time" < '2026-01-08T00:00:00Z' GROUP BY 1 ORDER BY 1 ASC) sub0) d WHERE "__time" >= time_bucket('6h', '2026-01-01T00:00:00Z'::timestamptz, 'Europe/Berlin') ORDER BY 1 DESC